import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/xhi23')
from lib import *
r=[]
r.append(R(6662295,"आम की रिलिश के साथ थाई शैली का हैलिबट",
"थाई खान-पान में \"मीठे\" और \"तीखे\" का संतुलित उपयोग उल्लेखनीय है। यह इस व्यंजन पर भी लागू होता है। \"तीखापन\" थाई मिर्चों से आता है और \"मिठास\" आम से। दोनों मिलकर न सिर्फ़ मीठे-तीखे का वह विशिष्ट मेल देते हैं, बल्कि मछली के लिए सालसा जैसी एक सुंदर और मुँह में पानी लाने वाली रिलिश भी बनाते हैं।",
"4","4 औंस मछली + 1/3 कप रिलिश",
["1 1/2 बड़े चम्मच ग्रेपसीड तेल (बाँटकर इस्तेमाल करें)","3 डंठल हरा प्याज़ (स्कैलियन) (पतला कटा हुआ, हरे और सफ़ेद हिस्से अलग-अलग)","1 छोटी थाई मिर्च या 1/2 छोटी हरी मिर्च (जैलापेन्यो) (बारीक कटी हुई)","1 बड़ा आम (सख़्त और पका हुआ, छिला, गुठली निकाला और 1/2 इंच के टुकड़ों में कटा (2 कप))","1 छोटा चम्मच सोया सॉस (प्राकृतिक रूप से किण्वित, कम सोडियम वाला)","1 बड़ा चम्मच 1/2 नींबू का रस","5 औंस के 4 हैलिबट फिले (पोंछकर सुखाए हुए)","1/2 छोटा चम्मच समुद्री नमक","1/4 छोटा चम्मच काली मिर्च (ताज़ा पिसी हुई)","1 बड़ा चम्मच ताज़ा हरा धनिया या तुलसी (ताज़ा कटा हुआ)"],
["एक मध्यम नॉनस्टिक स्किलेट में मध्यम आँच पर 1/2 बड़ा चम्मच तेल गरम करें। हरे प्याज़ का सफ़ेद हिस्सा और मिर्च डालें और प्याज़ के कैरेमलाइज़ होना शुरू होने तक भूनें, लगभग 3 1/2 मिनट। आम और सोया सॉस डालें और चलाते हुए पकाएँ, जब तक आम नरम न हो जाए, लगभग 7 मिनट। नींबू का रस और हरे प्याज़ का हरा हिस्सा मिलाएँ, एक कटोरे में निकालें और अलग रख दें।","मछली पर नमक और काली मिर्च छिड़कें। एक बड़े नॉनस्टिक स्किलेट में मध्यम-तेज़ आँच पर बचा हुआ 1 बड़ा चम्मच तेल गरम करें। फिले डालें और अंदर तक पकने और हल्का भूरा होने तक भूनें, हर तरफ़ लगभग 3 मिनट। (नोट: ज़रूरत हो तो बैच में बनाएँ।)","फिले के ऊपर आम की रिलिश डालें, हरा धनिया छिड़कें और परोसें।"]))
r.append(R(6664392,"मक्का और शिमला मिर्च के साथ ज़ुकीनी",
"यह साइड डिश आपके गर्मियों के बगीचे की या किसान बाज़ार से लाई सारी ज़ुकीनी और शिमला मिर्च के इस्तेमाल का एक बढ़िया तरीका है। बस थोड़े तीखेपन के साथ, यह व्यंजन आसानी से तैयार हो जाता है और ग्रिल्ड मछली या चिकन के साथ अच्छा लगता है।",
"8","1 कप",
["1/4 छोटा चम्मच काली मिर्च","1/2 छोटा चम्मच नमक","2 पूरे भुट्टे (छिलका और रेशे हटाए हुए, दाने भुट्टे से उतारे हुए (1 1/2 कप दाने))","4 मध्यम ज़ुकीनी (पतली कटी हुई)","1/2 पूरी हरी मिर्च (जैलापेन्यो) (बीज निकालकर बारीक कटी हुई)","1 मध्यम लाल शिमला मिर्च (कोर और बीज निकालकर छोटे टुकड़ों में कटी)","2 फांक लहसुन (बारीक कटा हुआ)","1 मध्यम प्याज़ (कटा हुआ)","1 1/2 बड़े चम्मच ज़ैतून का तेल"],
["एक बड़े स्किलेट में मध्यम आँच पर तेल गरम करें। प्याज़ डालें और 5 मिनट भूनें। लहसुन और लाल व हरी मिर्च डालकर 2 मिनट भूनें।","ज़ुकीनी डालें और 3 से 4 मिनट भूनें। स्किलेट में मक्का डालें और 2 से 4 मिनट भूनें। नमक और काली मिर्च से स्वाद बनाएँ।"]))
r.append(R(6664734,"टमाटर, जैतून और चिलगोज़े की सालसा के साथ ग्रिल्ड ज़ुकीनी बाइट्स",
"मधुमेह के अनुकूल इस रेसिपी से अपनी ग्रिल्ड ज़ुकीनी को और बेहतर बनाएँ। टमाटर, जैतून और चिलगोज़े से बनी ताज़ा सालसा कम कार्बोहाइड्रेट वाली ज़ुकीनी में एक चटपटा स्वाद जोड़ती है।",
"8","½ कप",
["1 मध्यम रोमा (प्लम) टमाटर (छोटे टुकड़ों में कटा)","1/4 कप कलामाता जैतून (बीज निकालकर बारीक कटे हुए)","3 बड़े चम्मच चिलगोज़े (पाइन नट्स) (भुने हुए)","2 बड़े चम्मच ताज़ा पार्सले (कटा हुआ)","3/4 छोटा चम्मच कोशर नमक (बाँटकर इस्तेमाल करें)","2 मध्यम ज़ुकीनी (¼ इंच चौड़े स्लाइस में कटी हुई)","1 बड़ा चम्मच नारियल तेल","1 फांक लहसुन (बारीक कटा हुआ)"],
["एक छोटे कटोरे में टमाटर, कलामाता जैतून, चिलगोज़े, पार्सले और ¼ छोटा चम्मच कोशर नमक मिलाएँ। एक तरफ़ रख दें।","ग्रिल पैन या ग्रिल को मध्यम-तेज़ आँच पर पहले से गरम करें।","एक कटोरे में ज़ुकीनी के स्लाइस को नारियल तेल, बारीक कटे लहसुन और ¼ छोटा चम्मच कोशर नमक के साथ मिलाएँ। ग्रिल पर रखें और हर तरफ़ 3 मिनट ग्रिल करें।","हर स्लाइस को गरम परोसें और ऊपर से भरपूर सालसा डालें।"]))
r.append(R(6664964,"फ़ेटा के साथ भुना यूनानी बैंगन",
"साइड डिश को बाद में सोची गई चीज़ नहीं समझना चाहिए। वे मुख्य व्यंजनों जितने ही पाक-प्रेम और ध्यान की हक़दार हैं। अगर आप ऐसी साइड डिश ढूँढ रहे हैं जो प्रभावित करे, तो यह भुने बैंगन की रेसिपी वही है। ताज़ी जड़ी-बूटियों, फ़ेटा और नींबू के ज़ेस्ट का अंतिम स्पर्श इस साइड डिश को प्लेट के सितारे जैसा बना देता है।",
"4","2 टुकड़े",
["3 बड़े चम्मच मरीनारा सॉस","1 बड़ा चम्मच नींबू का रस","1 बड़ा चम्मच एक्स्ट्रा वर्जिन ज़ैतून का तेल","1 फांक लहसुन (बारीक कटा हुआ)","1/4 छोटा चम्मच समुद्री नमक","1/4 छोटा चम्मच पिसी दालचीनी","2 मध्यम बैंगन (हर एक लंबाई में चार टुकड़ों में कटा, डंठल हटाए हुए)","3 बड़े चम्मच ताज़ा पार्सले","1 बड़ा चम्मच ताज़ा पुदीना (कटा हुआ, या 1 छोटा चम्मच कटा ताज़ा ओरेगैनो)","3 बड़े चम्मच फ़ेटा चीज़ (बारीक चूरा किया हुआ)","1/2 बड़ा चम्मच नींबू का ज़ेस्ट"],
["ओवन को 400°F पर पहले से गरम करें। एक छोटे कटोरे में मरीनारा सॉस, नींबू का रस, तेल, लहसुन, नमक और दालचीनी को फेंटकर मिलाएँ। बैंगन के टुकड़ों को बिना ब्लीच किए बेकिंग पेपर बिछी बेकिंग शीट पर छिलके वाली तरफ़ नीचे रखकर सजाएँ। बैंगन के टुकड़ों की कटी सतहों पर मरीनारा मिश्रण उदारता से ब्रश से लगाएँ।","बैंगन के टुकड़ों को पूरी तरह पकने तक भूनें, लगभग 30 मिनट।","थाली में निकालें, ऊपर से पार्सले, पुदीना, फ़ेटा और नींबू का ज़ेस्ट छिड़कें और परोसें।"]))
r.append(R(6665438,"पालक-आर्टिचोक डिप",
"यह कम कार्बोहाइड्रेट वाला स्टार्टर पारंपरिक पालक-आर्टिचोक डिप का कहीं हल्का रूप है, फिर भी इसमें बेहतरीन स्वाद है। अपनी अगली पार्टी के लिए इस डिप को झटपट तैयार कर लें।",
"12","2 बड़े चम्मच",
["1 1/2 कप जमे हुए आर्टिचोक हार्ट्स (कटे हुए और पिघलाए हुए)","1 कप जमा हुआ पालक (कटा हुआ, पिघलाया हुआ)","5 लाइट लहसुन और जड़ी-बूटी वाले चीज़ (वेजेस)","1 बड़ा चम्मच नींबू का रस (1/2 मध्यम नींबू से)","2 बड़े चम्मच लाइट मेयोनेज़","3 बड़े चम्मच पार्मेसन चीज़ (कद्दूकस किया हुआ)","1/4 छोटा चम्मच कुटी हुई लाल मिर्च के फ्लेक्स"],
["एक छोटे बर्तन में पालक और आर्टिचोक को 1 कप पानी में नरम होने तक उबालें। तरल फेंक दें, अच्छी तरह निथारें और आर्टिचोक व पालक को एक कटोरे में अलग रख दें।","उसी बर्तन में धीमी आँच पर Laughing Cow चीज़ के वेजेस पिघलाएँ। बाकी सामग्री डालें; अच्छी तरह मिलाएँ और 1-2 मिनट और पकाते रहें।","निथारे हुए पालक और आर्टिचोक को बर्तन में डालें और चलाएँ। 2 मिनट और पकाएँ।","अपनी पसंद की सब्ज़ियों या साबुत गेहूँ के क्रैकर्स के साथ गरमागरम परोसें।"]))
r.append(R(6665652,"लहसुनी भुना हुआ पालक",
"एक शानदार भोजन के लिए इस लहसुनी भुने पालक को डिजॉन सैल्मन रेसिपी के साथ परोसें। भुना हुआ लहसुन भी एक बढ़िया स्टार्टर बनता है। बस भुनी हुई लहसुन की फांकों को साबुत गेहूँ के क्रॉस्टिनी के साथ परोसें और अपने मेहमानों को टोस्ट पर लहसुन लगाने दें।",
"4","½ कप",
["1 गाँठ लहसुन (पूरा सिर)","1 बड़ा चम्मच ज़ैतून का तेल (बाँटकर इस्तेमाल करें)","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1/2 कप प्याज़ (बारीक कटा हुआ)","6 कप पालक","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च"],
["ओवन को 400°F पर पहले से गरम करें।","लहसुन की गाँठ को साबुत रखते हुए, उसके ऊपरी हिस्से से 1/4 से 1/2 इंच काट दें, जिससे लहसुन की अलग-अलग फांकें दिखने लगें। छिलका लगा रहने दें।","लहसुन की गाँठ को कटी हुई तरफ़ ऊपर करके फ़ॉइल की एक शीट पर रखें। लहसुन की गाँठ के कटे हिस्से पर 1 छोटा चम्मच ज़ैतून का तेल डालें। फ़ॉइल को लहसुन के चारों ओर मोड़ें और दबाकर बंद कर दें, ताकि एक पैकेट बन जाए।","400°F पर 30-35 मिनट बेक करें, या जब तक दबाने पर फांकें नरम न लगें।","लहसुन को छूने लायक थोड़ा ठंडा होने दें। भुनी हुई लहसुन की फांकों को छिलकों से निचोड़कर एक छोटे कटोरे में निकालें और काँटे से मसलकर पेस्ट बना लें।","एक बड़े सॉते पैन में मध्यम-तेज़ आँच पर बचा हुआ ज़ैतून का तेल और भरपूर कुकिंग स्प्रे डालें। प्याज़ डालें और कैरेमलाइज़ होना शुरू होने तक भूनें।","भुने लहसुन का पेस्ट डालें और प्याज़ पर लग जाने तक चलाएँ। पालक डालें और तब तक भूनें जब तक पालक मुरझाकर लहसुन और प्याज़ से लिपट न जाए।","नमक और काली मिर्च से स्वाद बनाएँ।"]))
r.append(R(6665803,"आसान चिकन सलाद टोस्ट",
"यह आसान चिकन सलाद बचे हुए पके चिकन का फिर से उपयोग करने का बढ़िया तरीका है। आप इसकी जगह डिब्बाबंद चिकन या टूना भी इस्तेमाल कर सकते हैं। अतिरिक्त सब्ज़ियों के लिए अपने ओपन-फ़ेस सैंडविच में पालक, लेट्यूस या रॉकेट पत्ते (अरुगुला) जैसी हरी पत्तेदार सब्ज़ियाँ डालें। कम कार्बोहाइड्रेट विकल्प के लिए, इसे टोस्ट की बजाय लेट्यूस रैप के रूप में परोसें।",
"4","1 ओपन-फ़ेस सैंडविच",
["2 कप कतरा हुआ या छोटे टुकड़ों में कटा पका चिकन","1/4 कप लाइट मेयोनेज़","1/4 कप सादा बिना वसा वाला ग्रीक योगर्ट","2 बड़े चम्मच बारीक कटा प्याज़","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1 छोटा चम्मच सूखा सोआ (डिल)","4 स्लाइस साबुत गेहूँ की ब्रेड (टोस्ट की हुई)","1/4 कप बादाम के पतले टुकड़े"],
["एक कटोरे में चिकन, लाइट मेयोनेज़, ग्रीक योगर्ट, बारीक कटा प्याज़, नमक, काली मिर्च और सूखा सोआ मिलाएँ।","टोस्ट के एक टुकड़े पर ½ कप चिकन सलाद का मिश्रण रखें। ऊपर 1 बड़ा चम्मच भुने हुए बादाम के पतले टुकड़े डालें।","बाकी 3 टोस्ट के टुकड़ों के साथ यही दोहराएँ, या चिकन सलाद को मेवों से अलग एयरटाइट डिब्बे में 1 सप्ताह तक फ्रिज में रखें और ज़रूरत के अनुसार ओपन-फ़ेस सैंडविच बनाएँ।"]))
r.append(R(6666824,"कुरकुरे खीरे के सलाद के साथ तीखा कोरियन चिकन",
"यह कम कार्बोहाइड्रेट और कम वसा वाली रेसिपी है जिसमें कोरियाई शैली से प्रेरित तीखा चिकन व्यंजन है, जो गोचुजांग से तेज़ तीखापन लाता है, यह एक किण्वित लाल मिर्च का पेस्ट है जो गाढ़ा, चटपटा और थोड़ा मीठा होता है, और इसे एक ठंडे, कुरकुरे खीरे के सलाद से संतुलित करता है। कम वसा वाले चिकन ब्रेस्ट और हल्के मीठे मैरिनेड का उपयोग भोजन को चीनी या वसा से लादे बिना स्वादिष्ट बनाए रखता है। यह मधुमेह वाले उन लोगों के लिए बढ़िया विकल्प है जो अपने ब्लड ग्लूकोज़ (रक्त शर्करा) का ध्यान रखते हुए जीवंत स्वादों का आनंद लेना चाहते हैं।",
"4","3 औंस चिकन + ½ कप खीरे का सलाद",
["12 औंस बिना हड्डी और बिना त्वचा के चिकन ब्रेस्ट (टेंडरलॉइन के रूप में कटे हुए)","5 पूरे हरे प्याज़ (स्कैलियन) (कटे हुए)","2 फांक लहसुन (मोटा कटा हुआ)","1 बड़ा चम्मच कम सोडियम वाला सोया सॉस","1/3 कप श्रीराचा या गोचुजांग सॉस","1 1/2 छोटे चम्मच ब्राउन शुगर के विकल्प का मिश्रण","1 बड़ा चम्मच तिल का तेल","2 बड़े चम्मच राइस वाइन विनेगर","1 पूरा इंग्लिश खीरा (पतला कटा हुआ)","1 पूरी लंबी लाल मिर्च (बीज निकालकर बारीक कटी हुई)","1/4 कप ताज़ा हरा धनिया (मोटा कटा हुआ)","1 बड़ा चम्मच तिल"],
["ब्लेंडर या फ़ूड प्रोसेसर में तीन मोटे कटे हरे प्याज़, लहसुन, सोया सॉस, गोचुजांग, ब्राउन शुगर का विकल्प, तिल का तेल और राइस वाइन विनेगर मिलाएँ। चिकना होने तक ब्लेंड करें।","चिकन टेंडरलॉइन को एक बड़े री-सील होने वाले प्लास्टिक बैग या उथली डिश में रखें। मैरिनेड को चिकन पर डालें, परोसने के लिए 2 बड़े चम्मच बचाकर रखें। बैग को सील करें या डिश को ढक दें और कम से कम 20 मिनट मैरिनेट करने के लिए फ्रिज में रखें।","एक मध्यम कटोरे में कटे हुए खीरे, कटी लाल मिर्च, कटा हरा प्याज़ और हरा धनिया मिलाएँ।","एक छोटे कटोरे में राइस वाइन विनेगर और ½ छोटा चम्मच ब्राउन शुगर का विकल्प तब तक फेंटें जब तक चीनी घुल न जाए। इस ड्रेसिंग को खीरे के मिश्रण पर डालें और अच्छी तरह मिलाएँ। एक तरफ़ रख दें।","हल्का तेल लगे ग्रिल पैन या स्किलेट को मध्यम आँच पर पहले से गरम करें।","चिकन को मैरिनेड से निकालें और अतिरिक्त मैरिनेड टपकने दें। चिकन को ग्रिल पैन पर रखें और 6-8 मिनट पकाएँ, बीच-बीच में पलटते रहें, जब तक चिकन अंदर तक न पक जाए और हल्का जल न जाए।","बचाए हुए मैरिनेड को ऊपर से डालें और 1 बड़ा चम्मच भुने हुए तिल और दो कटे हुए हरे प्याज़ छिड़कें।"]))
r.append(R(6666899,"ब्लड ऑरेंज विनिग्रेट के साथ सेब, चुकंदर और गाजर का स्लॉ",
"मैंने यह स्वादिष्ट स्लॉ वाशिंगटन, डी.सी. के एक प्राथमिक विद्यालय में स्वयंसेवा करते समय \"खोजा\", जहाँ बच्चों ने बताया कि उनका पसंदीदा भोजन \"ABC सलाद\" है, जिसे वे स्कूल के बगीचे की सामग्री से बनाते थे! बच्चों को इतने आनंद से सब्ज़ियाँ खाते देखना इतना प्रेरणादायक था कि मैं भी इसकी प्रशंसक बन गई! मैंने इसे अपनी \"Culinary Medicine Made Easy\" कुकिंग क्लास में और जितने हो सके उतने मेनू में शामिल करना भी शुरू कर दिया।",
"4","1 कप",
["1 मध्यम चुकंदर (ताज़ा, छिला और कद्दूकस किया हुआ)","2 मध्यम गाजर (छिली और कद्दूकस की हुई)","1 बड़ा ग्रैनी स्मिथ या अन्य खट्टा सेब (छिला और कद्दूकस किया हुआ)","1/4 कप अखरोट (कटे हुए)","3 बड़े चम्मच कटा हुआ ताज़ा पार्सले, सोआ, या दोनों का मिश्रण","1/4 कप 1 ब्लड ऑरेंज का रस","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","2 बड़े चम्मच ज़ैतून का तेल"],
["कद्दूकस किए हुए चुकंदर, गाजर और सेब को मिक्सिंग बाउल में रखें और मिलाएँ। मिश्रण के ऊपर अखरोट और हरी जड़ी-बूटी(याँ) डालें और कटोरे को एक तरफ़ रख दें।","एक छोटे कटोरे में ब्लड ऑरेंज का रस और नमक तब तक फेंटें जब तक नमक घुल न जाए। 3–4 बार काली मिर्च पीसकर डालें, फिर तेल फेंटकर मिलाएँ। ड्रेसिंग को सलाद पर डालें और अच्छी तरह मिलाएँ ताकि समान रूप से लग जाए। जड़ी-बूटियों और ड्रेसिंग के साथ मिलाने के 1 घंटे के भीतर सलाद परोस दें।"]))
r.append(R(6667936,"ग्रीन मशीन स्मूदी",
"इस स्वादिष्ट और पौष्टिक स्मूदी के साथ हरे रंग का आनंद लें! बिना स्टार्च वाली सब्ज़ियों से भरी यह मधुमेह के अनुकूल रेसिपी है जिसमें अधिकांश अन्य स्मूदी की तुलना में कार्बोहाइड्रेट कम है।",
"1","12 औंस",
["1 कप बेबी पालक","1/2 मध्यम एवोकाडो","1/2 कप खीरा (मोटा कटा हुआ)","1/2 कप बिना मीठा बादाम का दूध","1/2 कप बर्फ़"],
["पालक, एवोकाडो, खीरा, बादाम का दूध और बर्फ़ ब्लेंडर में डालें। चिकना और क्रीमी होने तक ब्लेंड करें।","एक ऊँचे गिलास में डालें और तुरंत आनंद लें।"]))
r.append(R(6669746,"शैम्पेन विनिग्रेट में भुनी हरी फलियाँ",
"चिकन, मछली या बीफ़ के किसी भी मुख्य व्यंजन के साथ परोसने के लिए यह सरल लेकिन शानदार साइड डिश बनाकर मेहमानों को प्रभावित करें। यह सब्ज़ी की साइड डिश एक शानदार सर्फ़ एंड टर्फ़ भोजन के साथ जोड़ने के लिए एकदम सही है।",
"6","3/4 कप",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 1/2 पाउंड ताज़ी हरी फलियाँ (सिरे कटे हुए)","1 बड़ा चम्मच और 1 छोटा चम्मच ज़ैतून का तेल (बाँटकर इस्तेमाल करें)","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1 बड़ा चम्मच लहसुन (बारीक कटा हुआ)","2 बड़े चम्मच शैम्पेन विनेगर","1 छोटा चम्मच डिजॉन सरसों","1 छोटा चम्मच चीनी का विकल्प","1/4 छोटा चम्मच कुटी हुई लाल मिर्च के फ्लेक्स"],
["ओवन को 400 डिग्री F पर पहले से गरम करें। बेकिंग शीट पर कुकिंग स्प्रे लगाएँ। एक तरफ़ रख दें।","एक बड़े कटोरे में हरी फलियों को 1 छोटा चम्मच ज़ैतून के तेल, नमक, काली मिर्च और लहसुन के साथ मिलाएँ। तैयार बेकिंग शीट पर डालें और 25 मिनट भूनें, या जब तक अंदर तक न पक जाएँ और भूरी होना शुरू न हो जाएँ।","जब हरी फलियाँ पक रही हों, तब 1 बड़ा चम्मच ज़ैतून का तेल, शैम्पेन विनेगर, डिजॉन सरसों, चीनी का विकल्प और कुटी लाल मिर्च के फ्लेक्स फेंटकर मिलाएँ। एक तरफ़ रख दें।","जब हरी फलियाँ भुन जाएँ, तो उन पर शैम्पेन विनिग्रेट डालें और अच्छी तरह मिलाएँ।"]))
r.append(R(6670382,"चिकन ब्रेस्ट, पका हुआ, 4 औंस",
"पके हुए चिकन ब्रेस्ट की पोषण संबंधी जानकारी।",
"1","4 औंस",
["4 औंस चिकन ब्रेस्ट (बिना त्वचा का, पका हुआ)"],[]))
r.append(R(6671502,"ग्रिल्ड टेरियाकी टूना पैकेट",
"फ़ॉइल के पैकेट में ग्रिल करने से सारे स्वाद आपस में मिल जाते हैं और सफ़ाई चुटकियों का काम है! अगर आपके पास ग्रिल नहीं है, तो आप इन्हें ओवन में बेक कर सकते हैं। इसे 375°F पर गरम करें और 20 मिनट बेक करें।",
"4","4 औंस टूना + 1/2 कप सब्ज़ियाँ",
["2 1/2 बड़े चम्मच कम सोडियम वाला सोया सॉस","2 1/2 बड़े चम्मच पानी","1 बड़ा चम्मच शहद","1 बड़ा चम्मच ताज़ा अदरक (कटा हुआ)","2 फांक लहसुन (बारीक कटा हुआ)","2 छोटे चम्मच भुना हुआ तिल का तेल","4 शीट एल्युमिनियम फ़ॉइल (हर एक 12 इंच लंबी)","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","12 औंस स्टर-फ्राई सब्ज़ी मिश्रण, ताज़ा या जमा हुआ","1 छोटा चम्मच बिना नमक वाला मसाला (जैसे Mrs. Dash या Salt-Free Spike)","1 पाउंड येलोफ़िन आही टूना स्टेक (4 भागों में बँटा, हर एक 4 औंस का, ताज़ा या जमा हुआ; अगर जमा हो तो इस्तेमाल से पहले पिघलाएँ)"],
["एक छोटे सॉसपैन में सोया सॉस, पानी, शहद, अदरक, तिल का तेल और लहसुन फेंटकर मिलाएँ। उबाल आने दें, फिर आँच धीमी करके उबलने दें। 7 से 8 मिनट उबलने दें, या जब तक सॉस गाढ़ी होकर थोड़ी चाशनी जैसी न हो जाए। ठंडा होने के लिए अलग रख दें।","बाहर की ग्रिल को मध्यम आँच पर पहले से गरम करें और हर फ़ॉइल शीट के एक तरफ़ कुकिंग स्प्रे करें।","एक मध्यम कटोरे में सब्ज़ियाँ, लहसुन और मसाला मिलाएँ।","सब्ज़ियों को फ़ॉइल के टुकड़ों में बराबर बाँटें। सब्ज़ियों के ऊपर टूना स्टेक का एक टुकड़ा रखें और टूना पर तैयार टेरियाकी सॉस का 1 बड़ा चम्मच डालें।","फ़ॉइल के सिरों को साथ लाकर कसकर तीन बार मोड़ें, जब तक बंद न हो जाए और एक पैकेट न बन जाए।","पैकेट को 20 मिनट ग्रिल करें। पैकेट खोलते समय सावधान रहें; भाप गरम हो सकती है।"]))
r.append(R(6671813,"मूँगफली की सॉस के साथ चिकन सींक",
"ये चिकन सींक स्वादिष्ट और बहुमुखी हैं। इन्हें कुछ सब्ज़ियों और ब्राउन राइस के साथ परोसकर मज़ेदार और स्वादिष्ट भोजन बनाएँ।",
"4","2 सींक + लगभग 2 बड़े चम्मच सॉस",
["8 साबुत बाँस की सींकें","1/2 छोटा चम्मच कोशर नमक","1/4 छोटा चम्मच काली मिर्च","1/3 कप कम वसा वाला पीनट बटर","1 बड़ा चम्मच कम सोडियम वाला सोया सॉस","1 बड़ा चम्मच शहद","1 बड़ा चम्मच राइस विनेगर","1 छोटा चम्मच तिल का तेल","1 फांक लहसुन (बारीक कटा हुआ)","1 छोटा चम्मच ताज़ा अदरक (कद्दूकस किया हुआ)","1/2 छोटा चम्मच हल्दी","3 बड़े चम्मच पानी","1 पाउंड बिना हड्डी और बिना त्वचा के चिकन ब्रेस्ट (1 इंच मोटी पट्टियों में कटे)"],
["अगर लकड़ी की सींकें इस्तेमाल कर रहे हैं, तो उन्हें जलने से रोकने के लिए कम से कम 30 मिनट पानी में भिगोएँ।","एक छोटे कटोरे में कोशर नमक, काली मिर्च, पीनट बटर, सोया सॉस, शहद, राइस विनेगर, तिल का तेल, बारीक कटा लहसुन, कद्दूकस किया अदरक और हल्दी को फेंटकर मिलाएँ। पानी धीरे-धीरे तब तक डालें जब तक सॉस की मनचाही गाढ़ाई न आ जाए।","मूँगफली की सॉस का 1/3 हिस्सा चिकन पर डालें और अच्छी तरह चलाएँ ताकि चिकन पर मैरिनेड लग जाए। 20 मिनट मैरिनेट करें।","ग्रिल या ग्रिल पैन को मध्यम-तेज़ आँच पर पहले से गरम करें।","चिकन को सींकों में पिरोएँ और लगभग 10 मिनट ग्रिल करें, बीच-बीच में पलटते रहें, जब तक चिकन का अंदरूनी तापमान 165 डिग्री F तक न पहुँच जाए और उस पर अच्छी तरह जले हुए निशान न आ जाएँ।","बची हुई मूँगफली की सॉस को ऊपर से डालें या डुबोने के लिए साथ में परोसें।"]))
r.append(R(6671815,"ज़ुकीनी और खजूर के मफ़िन",
"ये सफ़र के लिए पकड़ो-और-चलो वाला बढ़िया नाश्ता बनते हैं। आप चाहें तो इस रेसिपी से ज़ुकीनी ब्रेड की एक लोफ़ भी बना सकते हैं। बस पकाने का समय बढ़ाकर 50–60 मिनट कर दें।",
"12","1 मफ़िन",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे (या पेपर लाइनर)","1/3 कप कम कैलोरी वाला ब्राउन शुगर का विकल्प","1/2 कप एप्पलसॉस (बिना मीठा)","1/4 कप कैनोला तेल","4 बड़े अंडों की सफ़ेदी","1 छोटा चम्मच वनीला एक्सट्रैक्ट","1 कप गेहूँ का आटा (साबुत)","1 कप ओल्ड-फ़ैशन्ड रोल्ड ओट्स","2 छोटे चम्मच बेकिंग पाउडर","1 छोटा चम्मच बेकिंग सोडा","1/2 छोटा चम्मच नमक","1 छोटा चम्मच पिसी दालचीनी","1/4 कप बीज निकाले सूखे खजूर (कटे हुए)","2 कप ज़ुकीनी (कद्दूकस की हुई)"],
["ओवन को 350 डिग्री F पर पहले से गरम करें। मफ़िन टिन पर हल्का स्प्रे करें या पेपर मफ़िन कप लगाएँ। पैन को एक तरफ़ रख दें।","एक मध्यम कटोरे में ब्राउन शुगर का विकल्प, बिना मीठा एप्पलसॉस, तेल, अंडे की सफ़ेदी और वनीला मिलाएँ; अच्छी तरह मिलाएँ। एक तरफ़ रख दें।","एक बड़े कटोरे में आटा, ओट्स, बेकिंग पाउडर, बेकिंग सोडा, नमक, दालचीनी और खजूर मिलाएँ।","सूखी सामग्री के बीच में एक गड्ढा बनाएँ। चीनी वाला (गीला) मिश्रण सूखी सामग्री में एक साथ डालें और अच्छी तरह मिलाएँ।","ज़ुकीनी मिलाएँ। घोल को 12 मफ़िन कपों में बराबर बाँटें।","30 मिनट बेक करें या जब तक बीच में डाली गई टूथपिक साफ़ बाहर न आए।"]))
